select (select post_id from public.blog_post_translations where locale = 'en' and slug = $v$3d-rendering-vs-animation-vs-virtual-tour$v$), 'tr', r->>'slug', r->>'title', r->>'excerpt', r->>'html', r->'takeaways', r->>'seo_title', r->>'seo_description', r->>'focus_keyword', true, (r->>'word_count')::int
from d where (select post_id from public.blog_post_translations where locale = 'en' and slug = $v$3d-rendering-vs-animation-vs-virtual-tour$v$) is not null
on conflict (post_id, locale) do update set slug = excluded.slug, title = excluded.title, excerpt = excluded.excerpt, html = excluded.html, content = null,
  takeaways = excluded.takeaways, seo_title = excluded.seo_title, seo_description = excluded.seo_description, focus_keyword = excluded.focus_keyword, ready = true, word_count = excluded.word_count;
update public.blog_posts p set
  cover_alt = coalesce(p.cover_alt, '{}'::jsonb) || jsonb_build_object('tr', $v$İçeriden aydınlanan modern bir evin gece dış cephe render görseli$v$::text),
  faq = (
    select coalesce(jsonb_agg(
      jsonb_set(jsonb_set(f, '{q}', coalesce(f->'q', '{}'::jsonb) || jsonb_build_object('tr', x->>'q')), '{a}', coalesce(f->'a', '{}'::jsonb) || jsonb_build_object('tr', x->>'a'))
      order by i), '[]'::jsonb)
    from jsonb_array_elements(p.faq) with ordinality as e(f, i)
    left join jsonb_array_elements($v$[{"q":"360° görsel ile sanal tur arasındaki fark nedir?","a":"360° görsel, tek bir noktadan etrafınıza bakmanızı sağlar. Sanal tur ise birden fazla 360° noktayı birbirine bağlar; böylece izleyici odadan odaya geçebilir. Çoğu zaman kat planı, etkileşim noktaları (hotspot) ve bilgi alanlarıyla desteklenir."},{"q":"Tek bir 3D model sabit görsel, animasyon ve sanal tur için kullanılabilir mi?","a":"Evet, en verimli çalışma yöntemi de budur. Model ve malzemeler bir kez hazırlanır; ardından her format kendi kamera açılarını, ışık geçişlerini ve çıktısını ekler."},{"q":"Bir mimari animasyon ne kadar uzun olmalı?","a":"Web siteleri ve sosyal medya için genellikle 30–90 saniye en iyi sonucu verir. Daha uzun filmler, izleyicinin zaten ilgili olduğu lansman etkinlikleri ve yatırımcı sunumları için uygundur."}]$v$::jsonb) with ordinality as y(x, j) on j = i
  )
where p.id = (select post_id from public.blog_post_translations where locale = 'en' and slug = $v$3d-rendering-vs-animation-vs-virtual-tour$v$);
