-- Part 2 — Turkish for the 4 landing pages. Only adds Turkish next to the English text it
-- translates; your edits in the page builder and block order are kept.
-- Generated by: node scripts/landing-seed/tr-update.mjs
begin;
create or replace function pg_temp.add_tr(j jsonb, m jsonb) returns jsonb language sql immutable as $f$
  select case jsonb_typeof(j)
    when 'object' then (
      select coalesce(jsonb_object_agg(k, pg_temp.add_tr(v, m)), '{}'::jsonb) from jsonb_each(j) as e(k, v)
    ) || case when jsonb_typeof(j->'en') = 'string' and not (j ? 'tr') and m ? (j->>'en') then jsonb_build_object('tr', m->(j->>'en')) else '{}'::jsonb end
    when 'array' then (select coalesce(jsonb_agg(pg_temp.add_tr(v, m) order by i), '[]'::jsonb) from jsonb_array_elements(j) with ordinality as a(v, i))
    else j end
$f$;
with m as (select $p${"Request a quote":"Teklif alın","See our work":"Projelerimizi görün","Frequently asked *questions*":"Sıkça sorulan *sorular*","3D rendering services for developers":"Gayrimenkul geliştiriciler için 3D görselleştirme","3D Rendering Services for Real Estate Developers | VARI":"Gayrimenkul Projeleri İçin 3D Görselleştirme | VARI","Photorealistic 3D rendering services for real estate developers: exteriors, interiors, animations and virtual tours to sell off-plan, convince investors and win approvals.":"Gayrimenkul geliştiriciler için fotogerçekçi 3D görselleştirme: topraktan satış, yatırımcı sunumları ve ruhsat süreçleri için dış cephe, iç mekân, animasyon ve sanal tur.","For real estate developers":"Gayrimenkul geliştiriciler için","Sell your project *before* it is built":"Projenizi inşa edilmeden *önce* satın","Photorealistic exteriors, interiors, animations and virtual tours that carry your development from planning application to the last sale.":"Projenizi ruhsat başvurusundan son daire satışına kadar taşıyan fotogerçekçi dış cephe ve iç mekân görselleri, animasyonlar ve sanal turlar.","## 3D rendering services built for developers\n\nBuyers, banks and planning authorities decide long before the first stone is laid. Our **3D rendering services for real estate developers** turn drawings into images people trust — consistent across your website, property portals, brochures, site hoarding and social media.\n\nWe build one detailed 3D model of your project and use it for every format you need, so later views, animations and tours build on work already done.":"## Gayrimenkul geliştiriciler için tasarlanmış 3D görselleştirme\n\nAlıcılar, bankalar ve resmi kurumlar ilk taş konmadan çok önce karar verir. **Gayrimenkul geliştiriciler için 3D görselleştirme** hizmetimiz, çizimlerinizi insanların güvendiği görsellere dönüştürür; web sitenizde, emlak portallarında, broşürlerde, şantiye panosunda ve sosyal medyada tutarlı bir dille.\n\nProjenizin detaylı tek bir 3D modelini kurar ve ihtiyaç duyduğunuz her formatta kullanırız. Böylece sonraki görünümler, animasyonlar ve sanal turlar yapılmış işin üzerine inşa edilir.","What we deliver":"Neler teslim ediyoruz?","One model, *every* channel":"Tek model, *tüm* kanallar","Exterior renderings":"Dış cephe görselleri","Hero views, street and garden perspectives, dusk scenes and aerials in context.":"Ana görünümler, sokak ve bahçe perspektifleri, alacakaranlık sahneleri ve çevresiyle birlikte kuş bakışı görseller.","Interior renderings":"İç mekân görselleri","Show apartments furnished for your target buyer, with the specification they will receive.":"Hedef alıcınıza göre döşenmiş, teslim edilecek şartnameyle birebir örnek daireler.","Animation & virtual tours":"Animasyon ve sanal turlar","Walk-throughs for launch events and immersive tours for buyers who cannot visit.":"Lansman etkinlikleri için gezinti videoları, projeyi yerinde göremeyen alıcılar için sürükleyici sanal turlar.","Selected *exteriors*":"Seçili *dış cephe* projeleri","## How a developer project runs with us\n\n1. **Brief and file check** — plans, elevations, materials and your target buyer.\n2. **Draft cameras** — we agree the views before detailed work starts.\n3. **Materials and light** — the stage that makes images believable.\n4. **Final images** — in the formats you need for print, portals and social media.\n5. **Next formats** — animation or a virtual tour from the same model.\n\nPlanning the budget? Read our [rendering cost guide](/blog/architectural-rendering-cost) and how to [use visuals to sell off-plan](/blog/3d-rendering-for-real-estate-developers).":"## Bir gayrimenkul projesi bizimle nasıl ilerler?\n\n1. **Brif ve dosya kontrolü**: planlar, görünüşler, malzemeler ve hedef alıcınız.\n2. **Taslak kamera açıları**: detaylı çalışmaya başlamadan görünümleri birlikte belirleriz.\n3. **Malzeme ve ışık**: görselleri inandırıcı kılan aşama.\n4. **Final görseller**: baskı, emlak portalları ve sosyal medya için ihtiyaç duyduğunuz formatlarda.\n5. **Sonraki formatlar**: aynı modelden animasyon veya sanal tur.\n\nBütçe mi planlıyorsunuz? [Mimari görselleştirme fiyatları](/blog/mimari-gorsellestirme-fiyatlari) rehberimizi ve [topraktan satışta görselleştirmenin rolünü](/blog/gayrimenkul-projeleri-icin-3d-gorsellestirme) okuyun.","Developer *questions*":"Geliştiricilerden *sorular*","When should we order renderings?":"Render görselleri ne zaman sipariş etmeliyiz?","As soon as façades and layouts are stable — usually around the planning application — so the same images serve financing, approvals and the sales launch.":"Cepheler ve planlar netleştiği anda; genellikle ruhsat başvurusu civarında. Böylece aynı görseller finansman, onay süreçleri ve satış lansmanında kullanılır.","Which files do you need?":"Hangi dosyalara ihtiyacınız var?","Plans, elevations and sections (DWG, RVT, SKP or PDF), a materials list and a few reference images. A 3D model speeds things up but is not required.":"Planlar, görünüşler ve kesitler (DWG, RVT, SKP veya PDF), bir malzeme listesi ve birkaç referans görsel. Hazır bir 3D model süreci hızlandırır ama zorunlu değildir.","Can you work with our international team?":"Uluslararası ekibimizle çalışabilir misiniz?","Yes. We work remotely with clients in Europe and North America, with clear milestones and online reviews.":"Evet. Avrupa ve Kuzey Amerika’daki müşterilerimizle net ara teslimler ve çevrim içi değerlendirmelerle uzaktan çalışıyoruz.","Tell us about your *development*":"Projenizi bize *anlatın*","Interior visualization services":"İç mekân görselleştirme","Interior Rendering & Visualization Services | VARI Studio":"İç Mekân Render ve Görselleştirme Hizmetleri | VARI Studio","Photorealistic interior rendering services for interior designers, developers and homeowners: living spaces, kitchens, bathrooms and commercial interiors.":"İç mimarlar, gayrimenkul geliştiriciler ve ev sahipleri için fotogerçekçi iç mekân render hizmetleri: yaşam alanları, mutfaklar, banyolar ve ticari iç mekânlar.","Interior visualization":"İç mekân görselleştirme","Rooms you can *feel* before they exist":"Var olmadan önce *hissedebileceğiniz* mekânlar","Light, materials and mood rendered with the care of an interior photograph.":"Işık, malzeme ve atmosfer; bir iç mekân fotoğrafının özeniyle görselleştirilir.","## Interior rendering for every kind of space\n\nOur **interior rendering services** help interior designers win approval faster, developers show finished apartments while they are still a shell, and homeowners decide on materials before anything is ordered. We render living rooms, kitchens, bathrooms, bedrooms, offices, hospitality and retail interiors — and can also develop the interior concept itself.":"## Her tür mekân için iç mekân render\n\n**İç mekân render hizmetlerimiz** iç mimarların onayı daha hızlı almasına, gayrimenkul geliştiricilerin kaba inşaat hâlindeki daireleri bitmiş hâliyle göstermesine ve ev sahiplerinin sipariş vermeden önce malzemelere karar vermesine yardımcı olur. Salonlar, mutfaklar, banyolar, yatak odaları, ofisler, otel ve restoranlar ile mağaza iç mekânlarını görselleştiriyor; istenirse iç mimari konseptin kendisini de geliştiriyoruz.","Who it is for":"Kimler için?","Made for *decisions*":"*Karar* vermek için tasarlandı","Interior designers":"İç mimarlar","Present concepts and material options that clients approve with confidence.":"Müşterilerin gönül rahatlığıyla onayladığı konseptler ve malzeme alternatifleri sunun.","Developers":"Gayrimenkul geliştiriciler","Show the finished apartment and amenities long before handover.":"Bitmiş daireyi ve sosyal alanları teslimden çok önce gösterin.","Homeowners":"Ev sahipleri","Compare layouts, colours and finishes before spending a cent.":"Tek kuruş harcamadan önce yerleşimleri, renkleri ve kaplamaları karşılaştırın.","## What to send us\n\n- Floor plan with dimensions and ceiling heights\n- Elevations of kitchens, built-ins and feature walls\n- Materials, finishes, furniture and lighting choices\n- Two or three reference images for the mood you want\n\nOur [interior rendering guide](/blog/interior-rendering-guide) explains the process step by step.":"## Bize neler göndermelisiniz?\n\n- Ölçülü kat planı ve tavan yükseklikleri\n- Mutfak, sabit mobilyalar ve vurgu duvarlarının görünüşleri\n- Malzeme, kaplama, mobilya ve aydınlatma seçimleri\n- İstediğiniz atmosfer için iki üç referans görsel\n\n[İç mekân render rehberimiz](/blog/ic-mekan-render-rehberi) süreci adım adım anlatıyor.","Interior *projects*":"İç mekân *projeleri*","Let’s visualize your *interior*":"İç mekânınızı *görselleştirelim*","Architectural visualization for Germany":"Almanya için mimari görselleştirme","Architectural Visualization for Projects in Germany | VARI":"Almanya’daki Projeler İçin Mimari Görselleştirme | VARI","Photorealistic architectural visualization for architects and developers in Germany — exteriors, interiors and animation, with remote collaboration and clear milestones.":"Almanya’daki mimarlar ve gayrimenkul geliştiriciler için fotogerçekçi mimari görselleştirme: dış cephe, iç mekân ve animasyon; uzaktan iş birliği ve net ara teslimlerle.","Germany":"Almanya","Architectural visualization for *Germany*":"*Almanya* için mimari görselleştirme","For architects, developers and housing companies who need precise, photorealistic images for competitions, planning and marketing.":"Yarışmalar, ruhsat süreçleri ve pazarlama için hassas, fotogerçekçi görsellere ihtiyaç duyan mimarlar, gayrimenkul geliştiriciler ve konut şirketleri için.","## Precise architectural visualization for German projects\n\nGerman planning culture values precision: correct proportions, real materials and images that match the plans. Our **architectural visualization for Germany** is built on your drawings — Grundrisse, Ansichten and Schnitte — and on clear approval stages, so every image can stand in front of a planning committee, a jury or a buyer. One example is the [HNE Laboratory](/work/hne-laboratory) exterior for a project in Germany.\n\nWe work remotely with structured milestones: file check, draft cameras, materials and light, final images.":"## Almanya’daki projeler için hassas mimari görselleştirme\n\nAlman planlama kültürü hassasiyete önem verir: doğru oranlar, gerçek malzemeler ve planlarla birebir örtüşen görseller. **Almanya için mimari görselleştirme** hizmetimiz çizimleriniz (Grundrisse, Ansichten ve Schnitte; yani planlar, görünüşler ve kesitler) ve net onay aşamaları üzerine kuruludur. Böylece her görsel bir imar komisyonunun, bir jürinin ya da bir alıcının karşısında durabilir. Almanya’daki bir proje için hazırladığımız [HNE Laboratory](/work/hne-laboratory) dış cephe görselleri buna bir örnektir.\n\nYapılandırılmış ara teslimlerle uzaktan çalışıyoruz: dosya kontrolü, taslak kamera açıları, malzeme ve ışık, final görseller.","Our *services*":"*Hizmetlerimiz*","All services":"Tüm hizmetler","Do you work with German planning documents?":"Alman proje dokümanlarıyla çalışıyor musunuz?","Yes — DWG, RVT, SKP or PDF plans, elevations and sections, as well as material schedules.":"Evet. DWG, RVT, SKP veya PDF formatında planlar, görünüşler ve kesitlerin yanı sıra malzeme listeleriyle çalışıyoruz.","What does a visualization cost?":"Bir görselleştirme ne kadar tutar?","Each project is quoted individually after we see the drawings. Our cost guide explains typical market ranges in Germany.":"Her proje, çizimleri gördükten sonra ayrı olarak fiyatlandırılır. Maliyet rehberimiz Almanya’daki tipik piyasa aralıklarını açıklıyor.","Start your project in *Germany*":"*Almanya*’daki projenize başlayın","Architectural rendering for Spain":"İspanya için mimari render","Architectural Rendering for Projects in Spain | VARI Studio":"İspanya’daki Projeler İçin Mimari Render | VARI Studio","Photorealistic architectural rendering for developers, architects and interior designers in Spain: exteriors, interiors, animation and virtual tours.":"İspanya’daki gayrimenkul geliştiriciler, mimarlar ve iç mimarlar için fotogerçekçi mimari render: dış cephe, iç mekân, animasyon ve sanal turlar.","Spain":"İspanya","Architectural rendering for *Spain*":"*İspanya* için mimari render","Photorealistic visuals for off-plan sales, coastal villas, urban apartments and interior design projects — with project communication in Spanish.":"Topraktan satış, sahil villaları, şehir daireleri ve iç mimarlık projeleri için fotogerçekçi görseller; proje iletişimi İspanyolca da yürütülebilir.","## Architectural rendering for promotions in Spain\n\nOff-plan sales are central to new residential development in Spain, and buyers — local and international — decide from images. Our **architectural rendering for Spain** covers exteriors in natural light, furnished interiors with the specification buyers receive, amenities such as pools and gardens, and animations or virtual tours for buyers who cannot visit.\n\nWe work remotely, with milestones and reviews online. Planning your budget? See our guide to [rendering cost](/blog/architectural-rendering-cost).":"## İspanya’daki konut projeleri için mimari render\n\nTopraktan satış, İspanya’daki yeni konut projelerinin merkezindedir ve yerli ya da yabancı alıcılar kararlarını görsellere bakarak verir. **İspanya için mimari render** hizmetimiz; doğal ışıkta dış cepheleri, alıcının teslim alacağı şartnameyle döşenmiş iç mekânları, havuz ve bahçe gibi sosyal alanları ve projeyi yerinde göremeyen alıcılar için animasyon ya da sanal turları kapsar.\n\nAra teslimler ve çevrim içi değerlendirmelerle uzaktan çalışıyoruz. Bütçe mi planlıyorsunuz? [Mimari görselleştirme fiyatları](/blog/mimari-gorsellestirme-fiyatlari) rehberimize göz atın.","Selected *work*":"Seçili *projeler*","Can we work in Spanish?":"İspanyolca çalışabilir miyiz?","Yes — the website, our communication and the project reviews are available in Spanish, English and German.":"Evet. Web sitemiz, iletişimimiz ve proje değerlendirmeleri İspanyolca, İngilizce ve Almanca olarak yürütülebilir.","Which format suits an off-plan launch?":"Topraktan satış lansmanına hangi format uygun?","Usually a set of still renderings first, then an animation for the launch and a virtual tour for remote buyers.":"Genellikle önce bir sabit render seti, ardından lansman için bir animasyon ve uzaktaki alıcılar için bir sanal tur.","Plan the visuals for your *project*":"*Projenizin* görsellerini planlayalım"}$p$::jsonb as m)
update public.pages p set
  title = pg_temp.add_tr(p.title, m.m),
  seo = pg_temp.add_tr(p.seo, m.m),
  blocks = pg_temp.add_tr(p.blocks, m.m),
  draft = case when p.draft is null then null else pg_temp.add_tr(p.draft, m.m) end
from m
where p.slug in ($p$3d-rendering-services-for-developers$p$, $p$interior-visualization-services$p$, $p$architectural-visualization-germany$p$, $p$architectural-rendering-spain$p$)
returning p.slug;
commit;

-- Check: 5 Turkish articles and 4 landing pages with Turkish titles.
select 'articles' as what, count(*) from public.blog_post_translations where locale = 'tr' and ready
union all
select 'landing pages', count(*) from public.pages where title ? 'tr' and kind = 'custom';
